  "file_path": "<workspace>/lab\settlement.pkb.sql",
  "content": "create or replace package body s2_settlement as

  c_fee_rate         constant number       := 0.015;   -- комісія 1,5%
  c_status_cancelled constant varchar2(9)  := 'CANCELLED';

  -- Повертає статус замовлення; перевіряє існування окремо від агрегату,
  -- бо SUM без GROUP BY повертає рядок із NULL і не підіймає NO_DATA_FOUND.
  function order_status(p_order_id number) return s2_orders.status%type is
    l_status s2_orders.status%type;
  begin
    if p_order_id is null then
      raise_application_error(-20002, 'Ідентифікатор замовлення не може бути NULL');
    end if;

    select status
      into l_status
      from s2_orders
     where order_id = p_order_id;

    return l_status;
  exception
    when no_data_found then
      raise_application_error(-20001, 'Замовлення не знайдено: ' || p_order_id);
  end order_status;

  -- Сума позицій у повній точності NUMBER, без округлення.
  function items_total(p_order_id number) return number is
    l_items_total number;
  begin
    select nvl(sum(quantity * unit_price), 0)
      into l_items_total
      from s2_order_items
     where order_id = p_order_id;

    return l_items_total;
  end items_total;

  function order_total(p_order_id number) return number is
    l_status s2_orders.status%type;
  begin
    l_status := order_status(p_order_id);  -- контрактні -20002 / -20001
    -- Статус на суму позицій не впливає, зокрема для CANCELLED.
    return items_total(p_order_id);
  end order_total;

  function merchant_due(p_order_id number) return number is
    l_status s2_orders.status%type;
    l_due    number;
  begin
    l_status := order_status(p_order_id);

    if l_status = c_status_cancelled then
      return 0;
    end if;

    -- Округлення одне: на загальній виплаті, а не за окремими позиціями.
    l_due := round(items_total(p_order_id) * (1 - c_fee_rate), 2);

    return l_due;
  end merchant_due;

end s2_settlement;
/
"
}

